    # =========================================================================
    # TRACK 1: BAREM GỐC Y THÁI BÌNH — B4 HẬU QUẢ HUYẾT ĐỘNG & NGUYÊN TẮC ĐIỀU TRỊ
    # =========================================================================
    {"id": "PED50-B31", "track": "barem_goc", "type": "basic", "category": "Hậu quả mất nước", "section": "B4",
     "front": "Kể tên 4 hậu quả nguy hiểm của mất nước theo giáo trình YTB?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>1) Giảm thể tích tuần hoàn (tụt HA, thiểu niệu, sốc); 2) Rối loạn áp lực thẩm thấu (teo não hoặc phù não); 3) Rối loạn ion và toan kiềm (toan chuyển hóa); 4) Tổn thương tế bào không hồi phục và suy đa tạng.<br><br><b>💡 Lưu ý:</b><br>Toan chuyển hóa thường do mất Bicarbonat và giảm tưới máu mô (toan lactic).",
     "extra": "Giáo trình YTB Mục 4.1 (trang 6).",
     "tags": ["PED-50", "Barem-goc", "Hau-qua-mat-nuoc"]},
    {"id": "PED50-B32", "track": "barem_goc", "type": "cloze", "category": "Phác đồ A", "section": "B4",
     "text": "[Barem gốc] Phác đồ A (tại nhà): Uống ORS sau mỗi lần đi ngoài: trẻ &lt; 2 tuổi uống {{c1::50 – 100 ml}}; trẻ ≥ 2 tuổi uống {{c1::100 – 200 ml}}; tiếp tục ăn bú và bổ sung Kẽm {{c1::10 – 14 ngày}}.",
     "extra": "Giáo trình YTB Mục 4.2 (trang 6): Áp dụng khi chưa mất nước.",
     "tags": ["PED-50", "Barem-goc", "Phac-do-A"]},
    {"id": "PED50-B33", "track": "barem_goc", "type": "cloze", "category": "Phác đồ B", "section": "B4",
     "text": "[Barem gốc] Phác đồ B (tại cơ sở y tế): Cho uống dung dịch ORS thẩm thấu thấp liều {{c1::75 ml/kg}} trong vòng {{c1::4 giờ đầu}}, sau đó đánh giá lại tình trạng mất nước.",
     "extra": "Giáo trình YTB Mục 4.2 (trang 6): Áp dụng cho mất nước nhẹ và vừa.",
     "tags": ["PED-50", "Barem-goc", "Phac-do-B"]},
    {"id": "PED50-B34", "track": "barem_goc", "type": "cloze", "category": "Phác đồ C", "section": "B4",
     "text": "[Barem gốc] Phác đồ C (cấp cứu truyền tĩnh mạch): Tổng liều {{c1::100 ml/kg}} dung dịch Ringer Lactat hoặc NaCl 0,9%.",
     "extra": "Giáo trình YTB Mục 4.2 (trang 6): Áp dụng cho mất nước nặng.",
     "tags": ["PED-50", "Barem-goc", "Phac-do-C"]},
    {"id": "PED50-B35", "track": "barem_goc", "type": "cloze", "category": "Phác đồ C trẻ nhỏ", "section": "B4",
     "text": "[Barem gốc] Phác đồ C ở trẻ &lt; 12 tháng tuổi: Truyền tĩnh mạch {{c1::30 ml/kg}} trong 1 giờ đầu, sau đó truyền {{c1::70 ml/kg}} trong 5 giờ tiếp theo (tổng cộng {{c1::6 giờ}}).",
     "extra": "Giáo trình YTB Mục 4.2 (trang 6): Trẻ nhỏ truyền chậm hơn trẻ lớn để tránh quá tải tuần hoàn.",
     "tags": ["PED-50", "Barem-goc", "Phac-do-C"]},
    {"id": "PED50-B36", "track": "barem_goc", "type": "cloze", "category": "Phác đồ C trẻ lớn", "section": "B4",
     "text": "[Barem gốc] Phác đồ C ở trẻ ≥ 12 tháng tuổi: Truyền tĩnh mạch {{c1::30 ml/kg}} trong {{c1::30 phút đầu}}, sau đó truyền {{c1::70 ml/kg}} trong {{c1::2,5 giờ}} tiếp theo (tổng cộng {{c1::3 giờ}}).",
     "extra": "Giáo trình YTB Mục 4.2 (trang 6).",
     "tags": ["PED-50", "Barem-goc", "Phac-do-C"]},

    # =========================================================================
    # TRACK 1: BAREM GỐC Y THÁI BÌNH — B5 BA BÀI TOÁN TÍNH DỊCH BÙ KINH ĐIỂN
    # =========================================================================
    {"id": "PED50-B37", "track": "barem_goc", "type": "cloze", "category": "Bài toán 1", "section": "B5",
     "text": "[Barem gốc] Bài toán 1 (mất nước đẳng trương, trẻ 5 kg mất 10%): Tổng lượng nước cần truyền trong 24 giờ gồm nước mất {{c1::500 ml}} cộng nước duy trì {{c1::500 ml}} = {{c1::1000 ml}}.",
     "extra": "Giáo trình YTB Mục 5.1 (trang 7): Nước mất 5 kg × 10% = 500 ml; duy trì Holliday-Segar 5 kg × 100 ml = 500 ml.",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-1"]},
    {"id": "PED50-B38", "track": "barem_goc", "type": "cloze", "category": "Bài toán 1", "section": "B5",
     "text": "[Barem gốc] Bài toán 1: Tổng lượng Natri cần bù trong 24 giờ gồm Na duy trì (3 × 5 kg = {{c1::15 mEq}}) cộng Na mất theo dịch đẳng trương (154 × 0,5 L = {{c1::77 mEq}}) bằng tổng cộng {{c1::92 mEq}}.",
     "extra": "Giáo trình YTB Mục 5.1 (trang 7): Dịch đẳng trương tính theo nồng độ 154 mEq/L.",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-1"]},
    {"id": "PED50-B39", "track": "barem_goc", "type": "cloze", "category": "Bài toán 1", "section": "B5",
     "text": "[Barem gốc] Bài toán 1: Phối hợp dịch truyền cho tổng Na 92 mEq và tổng nước 1000 ml là {{c1::600 ml NaCl 0,9%}} kết hợp với {{c1::400 ml Glucose 5%}} (tỷ lệ {{c1::3 : 2}}).",
     "extra": "Giáo trình YTB Mục 5.1 (trang 7): 92 / 0,154 ≈ 600 ml muối; còn lại 400 ml đường.",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-1"]},
    {"id": "PED50-B40", "track": "barem_goc", "type": "cloze", "category": "Bài toán 2", "section": "B5",
     "text": "[Barem gốc] Bài toán 2 (mất nước nhược trương, 5 kg mất 10%, Na⁺ = 125 mEq/L): Lượng Na⁺ cần điều chỉnh ngoại bào tính theo công thức {{c1::(Na_mm – Na_bn) × 0,6 × P₀}} = (135 – 125) × 0,6 × 5 = {{c1::30 mEq}}.",
     "extra": "Giáo trình YTB Mục 5.2 (trang 8): Nâng Na lên ngưỡng an toàn 135 mEq/L; thể tích phân bố ECF là 0,6.",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-2"]},
    {"id": "PED50-B41", "track": "barem_goc", "type": "cloze", "category": "Bài toán 2", "section": "B5",
     "text": "[Barem gốc] Bài toán 2: Tổng lượng Na⁺ cần bù gồm Na điều chỉnh (30 mEq) + Na mất theo đẳng trương (77 mEq) + Na duy trì (15 mEq) = tổng cộng {{c1::122 mEq}} trong 1000 ml dịch.",
     "extra": "Giáo trình YTB Mục 5.2 (trang 8).",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-2"]},
    {"id": "PED50-B42", "track": "barem_goc", "type": "cloze", "category": "Bài toán 2", "section": "B5",
     "text": "[Barem gốc] Bài toán 2: Phối hợp dịch truyền cho tổng Na 122 mEq và tổng nước 1000 ml là {{c1::800 ml NaCl 0,9%}} kết hợp với {{c1::200 ml Glucose 5%}} (tỷ lệ {{c1::4 : 1}}).",
     "extra": "Giáo trình YTB Mục 5.2 (trang 8): 122 / 0,154 ≈ 800 ml muối; còn lại 200 ml đường.",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-2"]},
    {"id": "PED50-B43", "track": "barem_goc", "type": "cloze", "category": "Bài toán 3", "section": "B5",
     "text": "[Barem gốc] Bài toán 3 (mất nước ưu trương, 5 kg mất 10%, Na⁺ = 170 mEq/L): Công thức tính lượng nước không điện giải (nước tự do) là {{c1::(Na_bn / Na_mm) × [0,6P₀ – 0,6P]}} = (170 / 145) × 0,3 ≈ {{c1::350 ml}}.",
     "extra": "Giáo trình YTB Mục 5.3 (trang 9): P0 = 5 kg, P hiện tại = 4,5 kg; Na mong muốn chuẩn là 145 mEq/L.",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-3"]},
    {"id": "PED50-B44", "track": "barem_goc", "type": "cloze", "category": "Bài toán 3", "section": "B5",
     "text": "[Barem gốc] Bài toán 3: Trong 500 ml nước mất có 350 ml nước tự do và 150 ml dịch chứa điện giải; lượng Na⁺ thực tế mất là 154 × 0,15 L ≈ {{c1::23 mEq}}; cộng Na duy trì 15 mEq thành tổng {{c1::38 mEq}}.",
     "extra": "Giáo trình YTB Mục 5.3 (trang 9).",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-3"]},
    {"id": "PED50-B45", "track": "barem_goc", "type": "cloze", "category": "Bài toán 3", "section": "B5",
     "text": "[Barem gốc] Bài toán 3: Phối hợp dịch truyền cho tổng Na 38 mEq và tổng nước 1000 ml là {{c1::250 ml NaCl 0,9%}} kết hợp với {{c1::750 ml Glucose 5%}} (dung dịch nhược trương 1/4 đẳng trương, tỷ lệ {{c1::1 : 3}}).",
     "extra": "Giáo trình YTB Mục 5.3 (trang 9): 38 / 0,154 ≈ 250 ml muối; 750 ml đường.",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-3"]},
    {"id": "PED50-B46", "track": "barem_goc", "type": "basic", "category": "Bài toán 3", "section": "B5",
     "front": "Quy tắc an toàn sống còn chống phù não cấp khi bù dịch mất nước ưu trương theo sách YTB là gì?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Tốc độ hạ Natri máu không được vượt quá 0,5 mEq/L/giờ (tối đa không quá 10–12 mEq/L trong 24 giờ đầu); thời gian truyền dịch phải kéo dài trong 36–48 giờ.<br><br><b>💡 Lưu ý:</b><br>Hạ Natri quá nhanh làm nước ùa vào tế bào não đang ứ chất thẩm thấu gây phù não cấp tử vong.",
     "extra": "Giáo trình YTB Mục 5.3 (trang 9).",
     "tags": ["PED-50", "Barem-goc", "Bai-toan-3", "An-toan"]},

    # =========================================================================
    # TRACK 1: BAREM GỐC Y THÁI BÌNH — B6 CẤP CỨU RỐI LOẠN NATRI & KALI MÁU
    # =========================================================================
    {"id": "PED50-B47", "track": "barem_goc", "type": "cloze", "category": "Cấp cứu hạ Natri", "section": "B6",
     "text": "[Barem gốc] Khi trẻ hạ Natri máu cấp có triệu chứng thần kinh (co giật, hôn mê, Na⁺ &lt; 120 mEq/L), xử trí cấp cứu bằng tiêm tĩnh mạch nhanh {{c1::NaCl 3% liều 4 ml/kg}} trong {{c1::20 – 30 phút}}.",
     "extra": "Giáo trình YTB Mục 6.1 (trang 10): Nhằm nâng nhanh Natri thêm 3-5 mEq/L để dứt cơn co giật và chống tụt kẹt não.",
     "tags": ["PED-50", "Barem-goc", "Cap-cuu-ha-Natri"]},
    {"id": "PED50-B48", "track": "barem_goc", "type": "basic", "category": "Nguyên tắc bù Kali", "section": "B6",
     "front": "Điều kiện tiên quyết trước khi bắt đầu bù Kali đường tĩnh mạch ở trẻ em theo sách YTB là gì?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Trẻ bắt buộc phải có nước tiểu (đã đi tiểu được) nhằm loại trừ suy thận cấp vô niệu.<br><br><b>💡 Lưu ý:</b><br>Bù Kali cho bệnh nhi vô niệu sẽ gây tăng Kali máu cấp tính dẫn đến ngừng tim tức thì.",
     "extra": "Giáo trình YTB Mục 6.2 (trang 10).",
     "tags": ["PED-50", "Barem-goc", "Bu-Kali-an-toan"]},
    {"id": "PED50-B49", "track": "barem_goc", "type": "cloze", "category": "Giới hạn bù Kali", "section": "B6",
     "text": "[Barem gốc] Giới hạn an toàn khi bù Kali tĩnh mạch ngoại vi theo giáo trình YTB: nồng độ pha truyền không vượt quá {{c1::40 mEq/L (0,3%)}}; tốc độ truyền tối đa là {{c1::0,5 mEq/kg/giờ}}.",
     "extra": "Giáo trình YTB Mục 6.2 (trang 10).",
     "tags": ["PED-50", "Barem-goc", "Bu-Kali-an-toan"]},
    {"id": "PED50-B50", "track": "barem_goc", "type": "cloze", "category": "Cấp cứu tăng Kali", "section": "B6",
     "text": "[Barem gốc] Tăng Kali máu (K⁺ &gt; 5,5 mEq/L) — Bước 1: Ổn định màng tế bào cơ tim bằng tiêm tĩnh mạch chậm {{c1::Calcium gluconate 10% liều 0,5 ml/kg}} trong {{c1::5 phút}} dưới theo dõi ECG.",
     "extra": "Giáo trình YTB Mục 6.2 (trang 10): Chống rung thất và ngừng tim trong lúc chờ hạ Kali máu.",
     "tags": ["PED-50", "Barem-goc", "Tang-Kali"]},
    {"id": "PED50-B51", "track": "barem_goc", "type": "cloze", "category": "Cấp cứu tăng Kali", "section": "B6",
     "text": "[Barem gốc] Tăng Kali máu — Bước 2 (dịch chuyển Kali vào nội bào): Truyền Glucose 10% kèm Insulin nhanh theo tỷ lệ {{c1::0,1 UI Insulin}} cho mỗi {{c1::4 g Glucose}}; phối hợp khí dung {{c1::Salbutamol liều cao (2,5 – 5 mg)}}.",
     "extra": "Giáo trình YTB Mục 6.2 (trang 10): Kèm NaHCO3 1,4% nếu có toan chuyển hóa.",
     "tags": ["PED-50", "Barem-goc", "Tang-Kali"]},
    {"id": "PED50-B52", "track": "barem_goc", "type": "cloze", "category": "Cấp cứu tăng Kali", "section": "B6",
     "text": "[Barem gốc] Tăng Kali máu — Bước 3 (đào thải Kali ra ngoài): Tiêm Furosemide {{c1::1 – 2 mg/kg}}; uống hoặc thụt tháo nhựa trao đổi ion {{c1::Kayexalate}}; và {{c1::lọc máu cấp cứu}} nếu kháng trị.",
     "extra": "Giáo trình YTB Mục 6.2 (trang 10).",
     "tags": ["PED-50", "Barem-goc", "Tang-Kali"]},
    {"id": "PED50-B53", "track": "barem_goc", "type": "basic", "category": "Điện giải đồ", "section": "B2",
     "front": "Vai trò sinh lý chính của ion Clo (Cl⁻) và ion Bicarbonat (HCO₃⁻) trong máu trẻ em là gì?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Clo là anion chính ngoại bào duy trì cân bằng điện tích; Bicarbonat là hệ đệm kiềm ngoại bào quan trọng nhất duy trì pH máu.<br><br><b>💡 Lưu ý:</b><br>Khi nôn mất Clo gây kiềm chuyển hóa; khi tiêu chảy mất Bicarbonat gây toan chuyển hóa.",
     "extra": "Giáo trình YTB Bảng 2.1 (trang 4).",
     "tags": ["PED-50", "Barem-goc", "Dien-giai-Clo-HCO3"]},

    # =========================================================================
    # TRACK 2: EBM HIỆN ĐẠI & LÂM SÀNG — E0 TỔNG QUAN & NỀN TẢNG CẦN DÙNG NGAY
    # =========================================================================
    {"id": "PED50-E01", "track": "ebm", "type": "basic", "category": "Nền tảng cấp cứu", "section": "E0",
     "front": "Thứ tự ưu tiên xử trí ban đầu khi tiếp cận trẻ có rối loạn nước và điện giải nặng tại phòng cấp cứu là gì?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Đánh giá và xử trí cấp cứu các dấu hiệu đe dọa tính mạng (sốc giảm thể tích, co giật) trước khi làm xét nghiệm chi tiết.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Hồi sức tuần hoàn và giải tỏa phù não co giật bằng NaCl 3% là ưu tiên số 1 để bảo toàn tính mạng.",
     "extra": "Release Lesson PED-50 Mục 0.1.",
     "tags": ["PED-50", "EBM", "Tong-quan"]},
    {"id": "PED50-E02", "track": "ebm", "type": "basic", "category": "Guidelines AAP 2018", "section": "E0",
     "front": "Khuyến cáo của Viện Hàn lâm Nhi khoa Hoa Kỳ (AAP 2018) về dịch truyền duy trì ở trẻ nằm viện có gì thay đổi so với quan điểm truyền thống?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Khuyến cáo bắt buộc dùng dịch đẳng trương (NaCl 0.9%) làm dịch duy trì, thay thế hoàn toàn dịch nhược trương truyền thống.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Bệnh nhi nằm viện có kích thích tăng tiết ADH; dùng dịch nhược trương sẽ giữ nước tự do gây hạ Natri máu mắc phải tại viện (PMID: 30478247).",
     "extra": "AAP Guideline (Feld LG et al., Pediatrics 2018, PMID: 30478247).",
     "tags": ["PED-50", "EBM", "AAP-2018", "Dich-duy-tri"]},
    {"id": "PED50-E03", "track": "ebm", "type": "cloze", "category": "Guidance CJASN 2023", "section": "E0",
     "text": "Theo đồng thuận CJASN 2023 về xử trí tăng Natri máu ở trẻ em, tốc độ hạ Natri máu tối đa cho phép là {{c1::≤ 0,5 mEq/L/giờ}} (tối đa {{c1::10 – 12 mEq/L/24h}}).",
     "extra": "Somers MJ et al., Clin J Am Soc Nephrol 2023 (PMID: 36888887): Ngăn ngừa biến chứng phù não cấp và co giật tử vong.",
     "tags": ["PED-50", "EBM", "CJASN-2023", "Tang-Natri"]},
    {"id": "PED50-E04", "track": "ebm", "type": "basic", "category": "Dịch tễ PICU", "section": "E0",
     "front": "Nghiên cứu đoàn hệ 4.821 bệnh nhi PICU (BMC Pediatr 2026) ghi nhận tác động nào của hạ Natri máu lúc nhập viện?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Gặp ở 28,4% bệnh nhi và liên quan độc lập với tăng thời gian thở máy (OR = 1,62) cùng tăng nguy cơ tử vong (OR = 1,85).<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Hạ Natri máu là dấu ấn độc lập của bệnh nặng, đòi hỏi can thiệp cấp cứu kịp thời bằng NaCl 3% khi có co giật.",
     "extra": "Chen Y et al., BMC Pediatr 2026 (PMID: 42015038).",
     "tags": ["PED-50", "EBM", "Dich-te-PICU"]},

