    {"id": "PED50-E14", "track": "ebm", "type": "basic", "category": "Phân biệt SIADH và CSW", "section": "E2",
     "front": "Điểm khác biệt cốt lõi về thể tích tuần hoàn giữa hội chứng SIADH và CSW ở trẻ chấn thương/phẫu thuật thần kinh là gì?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>SIADH có thể tích tuần hoàn bình thường hoặc tăng nhẹ (Euvolemic); CSW có giảm thể tích tuần hoàn rõ rệt (Hypovolemic dehydration).<br><br><b>💡 Cơ chế / Lưu ý:</b><br>SIADH do ứ nước tự do qua ADH; CSW do thận thải muối qua ANP/BNP kèm mất nước qua thận.",
     "extra": "Release Lesson PED-50 Mục 2.3.",
     "tags": ["PED-50", "EBM", "SIADH", "CSW"]},
    {"id": "PED50-E15", "track": "ebm", "type": "basic", "category": "Xử trí SIADH vs CSW", "section": "E2",
     "front": "Tại sao nhầm lẫn CSW thành SIADH để hạn chế dịch là sai lầm nguy hiểm chết người?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Hạn chế dịch ở bệnh nhân CSW đang thiếu hụt thể tích tuần hoàn sẽ làm tụt huyết áp nặng dẫn tới thiếu máu và nhồi máu não diện rộng.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>CSW bắt buộc phải bù đủ muối và nước bằng NaCl 0.9%; SIADH mới áp dụng hạn chế nước tự do (50-75% nhu cầu).",
     "extra": "Release Lesson PED-50 Mục 2.3.",
     "tags": ["PED-50", "EBM", "SIADH", "CSW", "Bay"]},
    {"id": "PED50-E16", "track": "ebm", "type": "basic", "category": "Ringer Lactat vs NaCl 0.9%", "section": "E2",
     "front": "Tại sao Ringer Lactat được ưu tiên hơn NaCl 0.9% trong hồi sức sốc mất nước tiêu chảy ở trẻ em?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Ringer Lactat có nồng độ Clo sinh lý (109 mEq/L) và chứa Lactate chuyển hóa thành Bicarbonat giúp kiềm hóa toan máu; NaCl 0.9% có Clo cao (154 mEq/L) gây toan chuyển hóa tăng Clo.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Clo cao còn gây co thắt động mạch thận làm suy giảm mức lọc cầu thận.",
     "extra": "Release Lesson PED-50 Mục 2.4.",
     "tags": ["PED-50", "EBM", "Ringer-Lactat", "NaCl-09"]},
