    # =========================================================================
    # TRACK 2: EBM HIỆN ĐẠI & LÂM SÀNG — E5 CẤP CỨU CÁC RỐI LOẠN ĐIỆN GIẢI NGUY HIỂM
    # =========================================================================
    {"id": "PED50-E30", "track": "ebm", "type": "basic", "category": "Cơ chế Calcium gluconate", "section": "E5",
     "front": "Tại sao Calcium gluconate 10% tiêm tĩnh mạch lại là bước 1 trong tăng Kali máu nặng dù không làm giảm Kali máu?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Ion Canxi đối kháng điện thế trên màng tế bào cơ tim, nâng ngưỡng kích thích và ổn định màng, phòng ngừa rung thất ngay lập tức trong 5 phút.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Thuốc có tác dụng bảo vệ tim tức thì để tạo thời gian cho Bước 2 và Bước 3 hạ nồng độ Kali huyết thanh.",
     "extra": "Pediatr Nephrol 2024 Protocol (PMID: 38001558).",
     "tags": ["PED-50", "EBM", "Tang-Kali", "Canxi"]},
    {"id": "PED50-E31", "track": "ebm", "type": "cloze", "category": "Tỷ lệ Insulin Glucose", "section": "E5",
     "text": "Trong cấp cứu tăng Kali máu, phác đồ truyền tĩnh mạch dịch chuyển Kali vào nội bào dùng tỷ lệ: {{c1::0,1 UI Insulin nhanh}} cho mỗi {{c1::4 g Glucose}} (pha trong dung dịch Glucose 10%).",
     "extra": "Release Lesson PED-50 Mục 5.2: Tránh hạ đường huyết trong khi kích thích bơm Na+/K+-ATPase đưa Kali vào tế bào.",
     "tags": ["PED-50", "EBM", "Tang-Kali", "Insulin"]},
    {"id": "PED50-E32", "track": "ebm", "type": "basic", "category": "Cơ chế Salbutamol", "section": "E5",
     "front": "Cơ chế nào giúp khí dung Salbutamol liều cao (2,5–5 mg) hạ Kali máu trong cấp cứu?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Salbutamol kích thích chọn lọc thụ thể β2-adrenergic làm tăng hoạt tính bơm Na⁺/K⁺-ATPase, bơm Kali từ ngoại bào vào trong tế bào trong vòng 30 phút.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Tác dụng hiệp đồng hoàn hảo khi dùng phối hợp cùng Insulin-Glucose.",
     "extra": "Pediatr Nephrol 2024 Protocol (PMID: 38001558).",
     "tags": ["PED-50", "EBM", "Tang-Kali", "Salbutamol"]},
    {"id": "PED50-E33", "track": "ebm", "type": "basic", "category": "Nguy cơ tiêm IV push KCl", "section": "E5",
     "front": "Tại sao tuyệt đối cấm tiêm trực tiếp Kali Clorid (IV push) vào tĩnh mạch dưới mọi hình thức?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Gây tăng nồng độ Kali cục bộ cực cao tại buồng tim dẫn đến block nhĩ thất hoàn toàn, rung thất và ngừng tim tâm thu tức thì không hồi phục.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Bắt buộc phải pha loãng trong chai dịch truyền và kiểm tra tốc độ qua máy truyền dịch.",
     "extra": "Release Lesson PED-50 Mục 5.3 & Box đỏ.",
     "tags": ["PED-50", "EBM", "Bu-Kali", "An-toan"]},
    {"id": "PED50-E34", "track": "ebm", "type": "cloze", "category": "Cấp cứu hạ Canxi", "section": "E5",
     "text": "Cấp cứu hạ Canxi máu có co giật ở trẻ em: tiêm tĩnh mạch chậm {{c1::Calcium gluconate 10% liều 0,5 – 1 ml/kg}} (pha loãng gấp đôi với Glucose 5%) trong {{c1::10 – 20 phút}} dưới theo dõi nhịp tim.",
     "extra": "Nguyen TH et al., Front Endocrinol 2026 (PMID: 41704483): Cắt cơn co giật ở 96,7% bệnh nhi.",
     "tags": ["PED-50", "EBM", "Ha-Canxi"]},
    {"id": "PED50-E35", "track": "ebm", "type": "basic", "category": "Dịch tễ hạ Canxi", "section": "E5",
     "front": "Hai nguyên nhân hàng đầu gây hạ Canxi máu nặng ở trẻ em Việt Nam theo nghiên cứu đa trung tâm (Front Endocrinol 2026) là gì?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Còi xương do thiếu vitamin D (chiếm 68,3%) và suy tuyến cận giáp (chiếm 18,7%).<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Thiếu vitamin D làm giảm hấp thu Canxi ở ruột, thường gặp ở trẻ nhũ nhi ít tiếp xúc ánh nắng.",
     "extra": "Nguyen TH et al., Front Endocrinol 2026 (PMID: 41704483).",
     "tags": ["PED-50", "EBM", "Ha-Canxi", "Dich-te"]},
    {"id": "PED50-E36", "track": "ebm", "type": "basic", "category": "Tương tác Magie và Kali", "section": "E5",
     "front": "Tại sao hạ Magie máu lại gây ra tình trạng hạ Kali máu kháng trị với điều trị bù?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Vì Magie là đồng yếu tố ức chế kênh ROMK ở ống lượn xa; thiếu Magie làm kênh ROMK mở tự do gây thoát và mất Kali ồ ạt qua nước tiểu.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Chừng nào chưa bù đủ Magie thì mọi nỗ lực bù Kali đều bị đào thải qua thận.",
     "extra": "Release Lesson PED-50 Mục 5.5.",
     "tags": ["PED-50", "EBM", "Ha-Magie", "Ha-Kali"]},
    {"id": "PED50-E37", "track": "ebm", "type": "basic", "category": "Tương tác Magie và Canxi", "section": "E5",
     "front": "Tại sao hạ Magie máu nặng lại gây hạ Canxi máu kháng trị?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Thiếu Magie làm trơ tuyến cận giáp dẫn đến giảm bài tiết PTH, đồng thời gây đề kháng thụ thể PTH tại xương và ống thận.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Bệnh nhi co giật do hạ Canxi kèm hạ Magie bắt buộc phải được bù đồng thời Magie mới nâng được Canxi máu.",
     "extra": "Release Lesson PED-50 Mục 5.5.",
     "tags": ["PED-50", "EBM", "Ha-Magie", "Ha-Canxi"]},
    {"id": "PED50-E38", "track": "ebm", "type": "cloze", "category": "Xử trí hạ Magie cấp cứu", "section": "E5",
     "text": "Cấp cứu co giật hoặc xoắn đỉnh (Torsades de Pointes) do hạ Magie máu: tiêm tĩnh mạch {{c1::Magnesium Sulfate 20% liều 25 – 50 mg/kg}} (tối đa 2 g) pha loãng Glucose 5% truyền trong {{c1::30 – 60 phút}}.",
     "extra": "Release Lesson PED-50 Mục 5.5: Theo dõi monitor điện tim liên tục.",
     "tags": ["PED-50", "EBM", "Ha-Magie"]},
    {"id": "PED50-E39", "track": "ebm", "type": "basic", "category": "Ngộ độc tăng Magie", "section": "E5",
     "front": "Dấu hiệu cảnh báo sớm nhất của ngộ độc tăng Magie máu là gì và thuốc giải độc đặc hiệu là gì?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Dấu hiệu sớm nhất: mất phản xạ gân xương bánh chè (khi Mg &gt; 4 mEq/L); Thuốc giải độc đối kháng: Calcium gluconate 10% liều 0,5 ml/kg tiêm TM chậm.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Ion Canxi đối kháng trực tiếp tác dụng ức chế thần kinh cơ và tim mạch của ion Magie.",
     "extra": "Release Lesson PED-50 Mục 5.5.",
     "tags": ["PED-50", "EBM", "Tang-Magie", "Giai-doc"]},
    {"id": "PED50-E40", "track": "ebm", "type": "basic", "category": "Rối loạn toan kiềm", "section": "E5",
     "front": "Phân biệt rối loạn thăng bằng toan kiềm giữa tiêu chảy cấp mất nước và nôn trớ do hẹp phì đại môn vị?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Tiêu chảy: mất HCO₃⁻ qua phân + giảm tưới máu mô gây Toan chuyển hóa; Nôn hẹp môn vị: mất HCl dịch vị gây Kiềm chuyển hóa giảm Clo và giảm Kali máu.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Kiềm chuyển hóa giảm Clo trong hẹp môn vị bắt buộc phải bù dịch NaCl 0.9% kèm bù Kali.",
     "extra": "Release Lesson PED-50 Mục 5.6.",
     "tags": ["PED-50", "EBM", "Toan-kiem"]},

