    # =========================================================================
    # TRACK 2: EBM HIỆN ĐẠI & LÂM SÀNG — E9 CÁC CA LÂM SÀNG THỰC CHIẾN
    # =========================================================================
    {"id": "PED50-E53", "track": "ebm", "type": "basic", "category": "Case 1 lâm sàng", "section": "E9",
     "front": "Ca lâm sàng 1 (Bé Nam 10 tháng 8 kg, tiêu chảy 8 lần/ngày, mất nước vừa đẳng trương Na 138): Hướng xử trí dịch bù là gì?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Trẻ uống được, áp dụng Phác đồ B đường uống bằng ORS thẩm thấu thấp liều 75 ml/kg = 8 × 75 = 600 ml uống chậm bằng thìa trong 4 giờ đầu.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Đánh giá lại sau 4 giờ; nếu trẻ hết dấu hiệu mất nước thì chuyển sang Phác đồ A tại nhà.",
     "extra": "Release Lesson PED-50 Mục 9 (Case 1).",
     "tags": ["PED-50", "EBM", "Ca-lam-sang", "Case-1"]},
    {"id": "PED50-E54", "track": "ebm", "type": "basic", "category": "Case 2 lâm sàng", "section": "E9",
     "front": "Ca lâm sàng 2 (Bé Hoa 14 tháng 9 kg, mất nước nhược trương Na 116 co giật, tụt HA 70/45): Xử trí cấp cứu phút đầu gồm những gì?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>1) Tiêm tĩnh mạch ngay NaCl 3% liều 4 ml/kg = 36 ml trong 20 phút để dứt co giật giải tỏa phù não; 2) Đồng thời bolus Ringer Lactat 20 ml/kg = 180 ml trong 30 phút chống sốc.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Vừa hồi sức thể tích lòng mạch vừa điều chỉnh khẩn cấp áp lực thẩm thấu nội sọ.",
     "extra": "Release Lesson PED-50 Mục 9 (Case 2).",
     "tags": ["PED-50", "EBM", "Ca-lam-sang", "Case-2"]},
    {"id": "PED50-E55", "track": "ebm", "type": "basic", "category": "Case 2 lâm sàng", "section": "E9",
     "front": "Sau khi cắt co giật cho Bé Hoa (Case 2), mục tiêu nâng Natri máu trong 24 giờ tiếp theo được giới hạn như thế nào?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Nâng không quá 10–12 mEq/L trong 24 giờ đầu để phòng ngừa biến chứng hội chứng hủy myelin cầu não.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Bù phần thâm hụt Natri còn lại từ từ theo công thức bài toán số 2 bằng dịch tỷ lệ 4 muối : 1 đường.",
     "extra": "Release Lesson PED-50 Mục 9 (Case 2).",
     "tags": ["PED-50", "EBM", "Ca-lam-sang", "Case-2"]},
    {"id": "PED50-E56", "track": "ebm", "type": "basic", "category": "Case 3 lâm sàng", "section": "E9",
     "front": "Ca lâm sàng 3 (Bé Minh 18 tháng, sụt từ 10 kg xuống 9 kg mất nước ưu trương Na 168): Tính lượng nước không điện giải và phương án bù dịch?",
     "back": "<b>🎯 Trả lời cốt lõi:</b><br>Lượng nước không điện giải = (168/145) × [(0.6×10) – (0.6×9)] = 695 ml; Dùng dịch nhược trương 1/4 (1 NaCl 0.9% : 3 Glucose 5%), bù chậm chia đều trong 48 giờ.<br><br><b>💡 Cơ chế / Lưu ý:</b><br>Tốc độ truyền khoảng 42 ml/h; xét nghiệm Natri mỗi 4h đảm bảo tốc độ hạ ≤ 0,5 mEq/L/giờ.",
     "extra": "Release Lesson PED-50 Mục 9 (Case 3).",
     "tags": ["PED-50", "EBM", "Ca-lam-sang", "Case-3"]},

